  caster:{name:'游方法士',art:'enemy-sorcerer',type:'staff',base:[5,20,14,14,17,2,14,8],growth:[1,3.7,3.5,1.8,2.4,.5,1.8,1],skills:['fan-fire','fan-frost']},
