      this.syncInput();this.drawNotice(now);let label=({main:'异界三国 主菜单：新游戏、载入游戏、战斗模拟、设置、关于',create:'创建人物 · 难度与潜力',appearance:'创建人物 · 姓名与造型',record:'人物档案',load:'载入游戏'})[this.screen]||'异界三国';
