 function buildEnemies(id,phase,currentLevel){const d=H.definitions[id],f=d.battles[phase];if(f.roster)return f.roster().map(u=>{const level=f.level||d.fixedCombatLevel||10;return u.baseAttributes&&u.potentials?{...u,level,...G.attributesAt(u.baseAttributes,u.potentials,level)}:{...u,level};});if(f.duel){let u=companion(f.duel,f.level||d.fixedCombatLevel||10);if(f.trainingWeapon){const weapon={...I.create('weapon-'+u.weapon.type,'white','duel-training'),id:'training-'+f.duel,name:f.trainingWeapon,skills:f.trainingSkills||[{base:'sword-cut',name:'试招'}]},skills=W.forWeapon(weapon);u={...u,weapon,skills,priorities:W.prioritiesFor(skills),weaponProficiencies:{[u.weapon.type]:40}};}return [{...u,id:'duel-'+f.duel,experienceWeight:1}];}const Catalog=node?require('./enemy-catalog.js'):root.EnemyCatalog;return Catalog.roster(f.level||d.fixedCombatLevel||10,f.count,f.pattern,{army:!f.enemyKind}).map((u,i)=>({...u,id:id+'-foe-'+i,...(i===0&&f.leaderName?{name:f.leaderName}:{}),...(i===0&&f.leaderArt?{characterId:f.leaderArt}:{})}));}
 function enemies(id,phase,currentLevel){const f=H.definitions[id].battles[phase],boss=f.boss||f.duel||f.named||f.roster;return N.mixRoster(buildEnemies(id,phase,currentLevel),f.enemyRoles,{army:!f.enemyKind}).map(u=>({...u,...(boss?{boss:true,statusImmunities:[...new Set([...(u.statusImmunities||[]),'stun'])]}:{}),passives:[...new Set([...(u.passives||[]),...(f.temporaryPassives||[])])]}));}
 // 城镇日常人物长期保留；线索只指出当前需要前往的地点。
